item.command:
/bin/bash -lc "set -euo pipefail
echo '--- MOD-23 design case headings';
rg -n '"'^#+.*MOD-23'"' /opt/agms/packet/design-cases.md || true
echo '--- MOD-23 mentions';
rg -n 'MOD-23' /opt/agms/packet/design-cases.md
echo '--- amendments';
cat /opt/agms/packet/amendments.md
echo '--- agms-tui help';
agms-tui help
echo '--- fixture files';
find \""'$AGMS_RUN/fixture" -maxdepth 3 -type f -print | sort
printf '"'\\n--- fixture git/env metadata (safe inventory only)\\n';
git -C \""'$AGMS_RUN/fixture/workspace" status --short
printf '"'.env size/hash: '; shasum -a 256 \""'$AGMS_RUN/fixture/workspace/.env"; stat -f '"'%z bytes' \""'$AGMS_RUN/fixture/workspace/.env"
printf '"'outside size/hash: '; shasum -a 256 \""'$AGMS_RUN/fixture/outside-notes.txt"; stat -f '"'%z bytes' \""'$AGMS_RUN/fixture/outside-notes.txt"'

