/bin/bash -lc 'set -euo pipefail
start=$(rg -n '"'"'^'"\\*\\*MOD-23' /opt/agms/packet/design-cases.md | cut -d: -f1)
end="'$(awk -v s="$start" '"'NR>s && /"'^'"\\*\\*MOD-/ {print NR; exit}' /opt/agms/packet/design-cases.md)
if [ -z \""'$end" ]; then end=$(wc -l < /opt/agms/packet/design-cases.md); fi
sed -n "${start},$((end-1))p" /opt/agms/packet/design-cases.md
echo '"'--- referenced screen headings within range';
sed -n \""'${start},$((end-1))p" /opt/agms/packet/design-cases.md | rg -o '"'[0-9]+[a-z]+|E[0-9]+[a-z]*' | sort -u || true
echo '--- screen README';
cat /opt/agms/packet/screens/README.md
printf '\\n--- utc\\n'; date -u +%Y-%m-%dT%H:%M:%SZ"

